head.script:
const getMediasoupServerUrl = () => {
    const hostname = window.location.hostname;
    const port = '3002';

    // localhost인 경우 그대로 유지
    if (hostname === 'localhost' || hostname === '127.0.0.1') {
        return `https://localhost:${port}`;
    }

    // 다른 IP인 경우 해당 IP 사용 
    return `https://${hostname}:${port}`;
};

const MEDIASOUP_SERVER_URL = getMediasoupServerUrl();

// mediasoup 관련 변수들
let mediasoupSocket = null;
let device = null;
let sendTransport = null;
let recvTransport = null;
let videoProducer = null;
let audioProducer = null;
let consumers = new Map(); // consumerId -> {consumer, remoteVideo}
let remoteVideos = new Map(); // peerId -> video element info

// 기존 변수들 (채팅용은 그대로 유지) 
let localStream = null;
let chatSocket = null; // 채팅용 WebSocket (그대로 유지)
let isJoined = false;
let isMuted = false;
let isVideoOff = false;
let remoteUserInfo = new Map(); // 원격 사용자 정보 저장

// 사용자 정보 (고유 ID 생성)
const generateUserId = () => {
    const timestamp = Date.now();
    const random = Math.floor(Math.random() * 1000);
    return `user_${timestamp}_${random}`;
};

//사용자 정보
let currentUser = {
    userId: "",
    userName: "",
    userImage: "",
    channelName: "test"
};

//페이지 로드 되었을 때 
scwin.onpageload = function () {
    //소켓 초기화 
    scwin.initializeChatWebSocket();


    ////////////////////////////////////////////////////////////////////////////////////////////////////////////////
    const generateUniqueId = (prefix) => {
        return `${prefix}_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
    };
    const group = $p.getComponentById("mf_exa_popup_header"); // 헤더의 버튼 영역
    const close = $p.getComponentById("mf_exa_popup_header_control");
    const btnGroupId = generateUniqueId("btn_group");
    const saveId = generateUniqueId("btn_save");
    const versionId = generateUniqueId("btn_version");

    // 버튼 그룹 생성
    const btnGroup = $p.dynamicCreate(btnGroupId, "group", {
        className: "header-btn-group",
    }, group);


    if (btnGroup?.render) {
        group.insertBefore(btnGroup.render, close);
    }


    // 버튼 생성 → btnGroup에 삽입
    const save = $p.dynamicCreate(saveId, "button", {
        className: "btn-save header-btn",
        label: "저장",
    }, btnGroup);

    const version = $p.dynamicCreate(versionId, "button", {
        className: "btn-version",
    }, btnGroup);

    const btn_save = $p.getComponentById(saveId);

    //task 저장버튼
    btn_save.bind("onclick", function () {
        scwin.saveTask();
    });

    const btn_version = $p.getComponentById(versionId);
    btn_version.bind("onclick", function () {
        scwin.versionPopup();
    })


    /////////////////////////////////////////////////////////////////////////////////////////////////////
    //ifram, contents 높이 조절
    setInterval(() => {
        const iframe = document.querySelector('.cke_wysiwyg_frame');
        const contents = $p.getComponentById("cke_1_contents");

        const innerDoc = iframe?.contentDocument || iframe?.contentWindow?.document;
        const body = innerDoc?.body;

        if (iframe && body) {
            const scrollHeight = body.scrollHeight + 100;
            body.style.overflow = 'hidden';

            iframe.style.setProperty('height', scrollHeight + 'px', 'important');
            contents.style.setProperty('height', scrollHeight + 'px', 'important');
        }
    }, 300);


    ////////////////////////////////////////////////////////////////////////////////////////////////////////////////
    //사용자 정보
    let userInfo = $p.getParameter("userInfo");
    scwin.defaultImage = "https://raw.githubusercontent.com/dorazi0423/test/refs/heads/main/group1.png";
    currentUser.userId = userInfo.userId;
    currentUser.userName = userInfo.userName;
    currentUser.userImage = userInfo.userImage;


    ///////////////////////////////////////////////////////////////////////////////////////////////
    //문서 내용 불러오기
    scwin.taskInfo = "";
    scwin.taskId = 2;
    scwin.projectId = 7;
    scwin.getTask(scwin.taskId, scwin.projectId);

    // setTimeout(function () {
    //     scwin.fileButtonInit();
    // }, 100); // 에디터 부분에 파일추가

    /////////////////////////////////////////////////////////////////////

    // 채팅 불러오기 및 초기 세팅
    scwin.currentPage = 1; // 최초 로딩이 1페이지니까 다음은 2부터 시작
    scwin.isLoading = false; // 중복 호출 방지용 플래그
    scwin.hasMore = true; // 마지막 페이지에 도달하면 false로 바꾸기
    scwin.loadMoreData();

    //무한 스크롤
    const scrollArea = $p.getComponentById("comment_main_group");


    scrollArea.bind("onscroll", function () {
        const scrollTop = scrollArea.render.scrollTop;

        if (scrollTop <= 50) { // 화면 맨 위 근접했을 때
            scwin.loadMoreData(); // 이전 댓글 불러오기
        }
    });
    /////////////////////////////////////////////////////////////////////
    //파일
    scwin.filePageIndex = 1; //현재 파일 페이지
    scwin.filePageNum = 0; //파일 순번
    pageList.setCount(1);

    scwin.chatDate = new Set();

    scwin.snapShot = false; //버전에서 현재상태 저장여부
    scwin.originalData = {};
    scwin.changeEditor();
    scwin.previousHTML = "";
};

scwin.changeEditor = function () {
    const editorComponentId = "contents_editor";
    const editorComponent = $p.getComponentById(editorComponentId);

    if (!editorComponent) {
        console.warn(`[WebSquare AI] 에디터 컴포넌트 '${editorComponentId}'를 찾을 수 없습니다.`);
        return;
    }

    // CKEditor 인스턴스 직접 접근
    const ckInstance = CKEDITOR.instances["mf_exa_popup_wframe_contents_editor_"];
    Object.keys(CKEDITOR.instances).forEach(key => {
        console.log("인스턴스 ID:", key);
    });

    if (!ckInstance) {
        console.warn("[WebSquare AI] CKEditor 인스턴스를 찾을 수 없습니다.");
        return;
    }

    ckInstance.on("instanceReady", function () {
        scwin.previousHTML = contents_editor.getHTML(); // 초기값 설정
        console.log(scwin.previousHTML);

        ckInstance.on("change", function () {
            console.log("바뀜");
            const currentHTML = ckInstance.getData();
            console.log("지금 전체 파일");
            console.log(dls_allFile.getAllJSON());
            console.log("화면 파일");
            console.log(dls_file.getAllJSON());
            console.log(scwin.previousHTML);
            console.log(currentHTML);

            if (currentHTML !== scwin.previousHTML) {

                console.log("이전 내용:", scwin.previousHTML);
                console.log("현재 내용:", currentHTML);

                const parser = new DOMParser();
                const doc = parser.parseFromString(currentHTML, "text/html");

                // 이제 doc.body는 HTML을 DOM 구조로 표현한 객체!
                console.log("변환된 DOM:", doc.body);

                const prevNums = scwin.extractFileNums(scwin.previousHTML);
                const currNums = scwin.extractFileNums(currentHTML);

                const removedNums = prevNums.filter(num => !currNums.includes(num));
                const restoredNums = currNums.filter(num => !prevNums.includes(num));

                if (removedNums.length > 0) {
                    console.log("삭제된 파일:", removedNums);
                    scwin.removeFileGrid(removedNums);
                }
                if (restoredNums.length > 0) {
                    console.log("복구된 파일:", restoredNums);

                    const restoredFiles = [];

                    // DOM에서 .file-data 태그들을 다시 훑음
                    const tags = doc.body.querySelectorAll(".file-data");

                    for (let tag of tags) {
                        const num = Number(tag.getAttribute("data-num"));
                        if (restoredNums.includes(num)) {
                            restoredFiles.push({
                                name: tag.getAttribute("data-name") || "파일",
                                size: Number(tag.getAttribute("data-size")) || 0,
                                type: tag.getAttribute("data-type") || "application/octet-stream",
                                data: tag.getAttribute("href") || tag.getAttribute("src") || "",
                                num
                            });
                        }
                    }

                    // 그리드에 복구된 파일들 추가
                    scwin.addFileGrid(restoredFiles);
                }
            }

            scwin.previousHTML = currentHTML;
        });
    });
};

scwin.extractFileNums = function (html) {
    const tempContainer = document.createElement("div");
    tempContainer.innerHTML = html;

    const fileTags = tempContainer.querySelectorAll(".file-data");
    return Array.from(fileTags)
        .map(el => parseInt(el.getAttribute("data-num")))
        .filter(num => !isNaN(num));
}


//버전기록 불러와서 바인딩
scwin.versionLoad = function (data) {
    if (!scwin.snapShot) {
        scwin.snapShot = true;
        scwin.originalData = scwin.currentWorkSnapshot();
    }

    contents_editor.setHTML(data.taskVersionVo.content);
    dls_allFile.setJSON(data.taskVersionVo.fileSrcVo);
    dls_file.setJSON(data.taskVersionVo.fileSrcVo);
}

//현재 버전상태 가져오기
scwin.loadOriginalVersion = function () {
    if (scwin.originalData) {
        contents_editor.setHTML(scwin.originalData.content);
        dls_allFile.setJSON(scwin.originalData.fileSrc);
        dls_file.setJSON(scwin.originalData.fileSrc);
        scwin.snapShot = false;
    }
};

//현재 버전상태 저장하기
scwin.currentWorkSnapshot = function () {
    return {
        content: contents_editor.getHTML(),
        fileSrc: dls_allFile.getAllJSON()
    };
};


//버전관리 모달창 열리는 함수
scwin.versionPopup = function (e) {
    const versionPopupId = "task_version";
    const isOpen = $p.getComponentById(versionPopupId);

    if (isOpen) {
        $p.closePopup(versionPopupId);
    } else {
        let param = {
            "type": "json",
            "name": "taskInfo",
            "data": {
                "taskId": scwin.taskId,
            },
        };

        // 팝업 생성 옵션 지정
        let options = {
            id: versionPopupId,
            type: "wframePopup",
            width: "330",
            height: "500",
            top: "230",
            left: "1250",
            popupName: "버전기록",
            modal: false,
            closeAction: "scwin.popup_closeAction",
            customTitleBar: false,
            dataObject: param,
        };

        // 팝업 생성
        $p.openPopup("./versionModal.xml", options);
    }
};


//팝업창 닫기
scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    let popObj = $p.getPopupWindow(argRuntimeID);
    return true; //팝업 닫기 (반환 값이 true인 경우만 팝업이 닫힘)
};


//파일 버튼 생성
scwin.fileButtonInit = function () {
    const generateUniqueId = (prefix) => {
        return `${prefix}_${Date.now()}_${Math.floor(Math.random() * 1000)}`;
    };

    const editorHeader = $p.getComponentById("cke_1_top");
    const btnGroupId = generateUniqueId("btn_group");
    const fileBtnId = generateUniqueId("btn_fileUpload");
    const fileInputId = generateUniqueId("input_file");

    // 버튼 그룹 생성
    const btnGroup = $p.dynamicCreate(btnGroupId, "group", {
        className: "header-btn-group",
        style: "width:100px; height: 18px; padding-bottom: 5px;"
    }, editorHeader);


    // "파일 추가" 버튼 생성
    const fileBtn = $p.dynamicCreate(fileBtnId, "button", {
        className: "btn-upload header-btn",
        style: "cursor: pointer;",
        label: "파일 추가",
    }, btnGroup);

    // 숨겨진 input[type=file] 생성
    const fileInput = document.createElement("input");
    fileInput.type = "file";
    fileInput.id = fileInputId;
    fileInput.multiple = true;
    fileInput.style.display = "none";
    document.body.appendChild(fileInput);

    // 버튼 클릭 시 숨겨진 input 트리거
    const btn_fileUpload = $p.getComponentById(fileBtnId);
    btn_fileUpload.bind("onclick", function () {
        document.getElementById(fileInputId).click();
    });

    // input change 이벤트 처리
    document.getElementById(fileInputId).addEventListener("change", function () {
        const files = this.files;
    });

}

//task 정보 가져오기
scwin.getTask = function (taskId, projectId) {
    //  데이터 보내기
    const formData = new FormData();
    formData.append("projectId", projectId);

    // 서버로 전송
    $.ajax({
        url: `/InsWebApp/task/${taskId}.pwkjson`,
        type: "POST",
        data: formData,
        processData: false,
        contentType: false,
        success: async function (res) {
            const data = res.taskUpdateVo;
            scwin.taskInfo = data;

            header_title.setValue(data.taskTitle);
            // projectUserVo 리스트를 세팅


            //담당자(프로젝트 사용자 값 세팅)
            let userData = [];
            data.projectUserVo.forEach(user => {
                userData.push({ userId: user.userId, userName: user.userName });
            });
            dls_manager.setJSON(userData);

            //담당자 존재하면 값 세팅
            if (data.managerVo && data.managerVo.length > 0) {
                let selectedUserIds = [];
                data.managerVo.forEach(manager => {
                    selectedUserIds.push(manager.userId);
                });

                manager_input.setValue(selectedUserIds);
            }

            data.priority ? priority_select.setValue(data.priority) : "";
            data.tags ? tags_input.setValue(data.tags) : "";
            data.startDate ? start_date.setValue(data.startDate) : "";
            data.endDate ? end_date.setValue(data.endDate) : "";

            contents_editor.setHTML(data.content);


            const fileList = data.fileSrcVo;

            // HTML 에디터의 기존 내용 가져오기
            let html = contents_editor.getHTML();

            // DOM 파싱을 위한 임시 컨테이너 생성
            const container = document.createElement("div");
            container.innerHTML = html;

            // file-data 클래스를 가진 태그들을 순서대로 가져오기
            const fileTags = container.querySelectorAll(".file-data");

            // fileList 순서와 fileTags 순서가 일치한다고 가정하고 data-num 추가
            fileList.forEach((item, index) => {
                item.num = ++scwin.filePageNum;

                const el = fileTags[fileTags.length - 1 - index];

                if (el) {
                    el.setAttribute("data-num", item.num);
                }
            });

            contents_editor.setHTML(container.innerHTML);
            scwin.previousHTML = contents_editor.getHTML();

            console.log(container.innerHTML);
            dls_allFile.setJSON(data.fileSrcVo);
            dls_file.setJSON(data.fileSrcVo);

            // setTimeout(() => {
            //     if (contents_editor.getHTML().trim() === "") {
            //         console.log("⚠️ 내용 사라짐. 복구 시도!");
            //         contents_editor.setHTML(scwin.lastEditorHtml);
            //         scwin.previousHTML = scwin.lastEditorHtml;
            //     }
            // }, 1500);

        },
        error: async function (err) {
            await $c.win.alert("저장 실패! 다시 시도해주세요");
        }
    });
}


//해당 작업에 대한 채팅 불러오기(20개씩)
scwin.loadMoreData = function () {
    if (scwin.isLoading || !scwin.hasMore) return;

    scwin.isLoading = true;

    const param = {
        page: scwin.currentPage
    };
    dma_getComment.setJSON(param);
    sbm_comment_get.action = `/InsWebApp/comment/${scwin.taskId}.pwkjson`;
    $c.sbm.execute(sbm_comment_get);
};

//소켓 초기화
scwin.initializeChatWebSocket = function () {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.hostname;
    const port = window.location.port || (protocol === 'wss:' ? '443' : '80');

    // 여러 WebSocket URL 시도
    const wsUrls = [
        `${protocol}//${host}:${port}/InsWebApp/chat`,
        `ws://localhost:9093/InsWebApp/chat`,
        `wss://localhost:19443/InsWebApp/chat`
    ];

    let wsUrl = wsUrls[0];
    console.log("WebSocket 연결 시도:", wsUrl);

    try {
        chatSocket = new WebSocket(wsUrl);

        chatSocket.onopen = function () {
            console.log("✅ WebSocket 연결 성공");

            // 채널 참가
            const joinMessage = {
                type: 'join',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName
            };
            chatSocket.send(JSON.stringify(joinMessage));

            // 채팅 히스토리 요청
            setTimeout(() => {
                const historyMessage = {
                    type: 'history',
                    channelName: currentUser.channelName,
                    afterTimestamp: 0
                };
                chatSocket.send(JSON.stringify(historyMessage));
                console.log("채팅 히스토리 요청 전송");
            }, 1000);
        };

        chatSocket.onmessage = function (event) {
            try {
                const data = JSON.parse(event.data);
                console.log("WebSocket 메시지 수신:", data.type, data);

                switch (data.type) {
                    // 채팅 메시지 처리 (동일)
                    case 'message':
                        if (data.userId !== currentUser.userId) {

                            console.log("다른 사용자 메시지:", data.userName, "->", data.message);
                            console.log(data);
                            const todayText = scwin.formatDate(new Date());

                            // chatDate에 오늘 날짜가 없으면 추가
                            if (!scwin.chatDate.has(todayText)) {
                                const dateComp = scwin.addChatDate(todayText);
                                scwin.chatDate.add(todayText);
                            }

                            scwin.addChatMessage(data.userName, data.message, data.createdAt, false, data.userImage, data.commentId);
                        } else {
                            console.log("내 메시지 서버 에코 무시:", data.message);
                        }
                        break;

                    case 'history':
                        if (data.messages && data.messages.length > 0) {
                            console.log("채팅 히스토리 로드:", data.messages.length, "개");

                            //dlt_chatMessages.removeAll();
                            //addedMessageIds.clear();

                            // data.messages.forEach(msg => {
                            //     const isOwn = msg.userId === currentUser.userId;
                            //     const msgId = msg.messageId || `history_${msg.userId}_${msg.timestamp}`;
                            //     scwin.addChatMessage(msg.userName, msg.message, isOwn, msgId);
                            // });

                            //scwin.addChatMessage("시스템", `이전 채팅 ${data.messages.length}개를 불러왔습니다.`, false);
                        } else {
                            console.log("채팅 히스토리 없음");
                        }
                        break;

                    case 'existing-users':
                        // 기존 사용자들과 webRTC 연결 시작 (화상통화 중일 때만)
                        console.log("기존 사용자들:", data.users, "내 화상통화 상태:", isJoined);

                        // 기존 사용자 정보 저장
                        if (data.userInfos) {
                            data.userInfos.forEach(user => {
                                remoteUserInfo.set(user.userId, user);
                                console.log("기존 사용자 정보 저장:", user.userName, user.userId);
                            });
                        }

                        // P2P 관련 코드 제거됨 - mediasoup에서 자동 처리
                        break;

                    case 'user-joined':
                        //scwin.addChatMessage("시스템", `${data.userName}님이 참가했습니다.`, false);

                        // 새 사용자 정보 저장
                        if (data.userId && data.userName) {
                            remoteUserInfo.set(data.userId, {
                                userId: data.userId,
                                userName: data.userName
                            });
                            console.log("새 사용자 정보 저장:", data.userName, data.userId);
                        }

                        // P2P 관련 코드 제거됨 - mediasoup에서 자동 처리
                        break;

                    case 'user-left':
                        //scwin.addChatMessage("시스템", `${data.userName}님이 나갔습니다.`, false);

                        if (data.userId) {
                            remoteUserInfo.delete(data.userId);
                            console.log("사용자 정보 제거:", data.userName, data.userId);
                        }

                        scwin.removeRemoteUser(data.userId);
                        break;

                    // P2P WebRTC 메시지 처리 제거됨 - mediasoup SFU 방식으로 대체됨

                    case 'notification':
                        //scwin.addChatMessage("시스템", data.message, false);
                        break;
                    case 'delete-message':
                        console.log("삭제 메시지 수신:", data.messageId);

                        const group = $p.getComponentById("mf_exa_popup_wframe_comment_main_group");
                        const children = group.getChildren ? group.getChildren() : [];
                        // console.log("group: " + group);
                        // console.log("children: " + children);


                        for (let i = 0; i < children.length; i++) {
                            const comp = children[i];
                            const compId = comp?.id || "undefined";
                            const userData = comp?.userData || "없음";
                            const localMessageId = userData?.commentId;
                            const match = String(localMessageId) === String(data.commentId);

                            // console.log(`[${i}] 컴포넌트 ID: ${compId}`);
                            // console.log(` -> userData:`, userData);
                            // console.log(` -> localMessageId: ${localMessageId} vs 삭제 대상: ${data.commentId}`);
                            // console.log(` -> 일치 여부: ${match}`);
                            if (match) {
                                // console.log(`✅ 매칭 성공 → 컴포넌트 제거: ${compId}`);
                                scwin.deleteChat(comp);
                                break;
                            }
                        }
                        break;

                    default:
                        console.warn("알 수 없는 메시지 타입:", data.type, data);
                        break;
                }
            } catch (error) {
                console.error("❌ 메시지 처리 오류:", error);
                //scwin.addChatMessage("시스템", "❌ 메시지 처리 중 오류 발생", false);
            }
        };

        chatSocket.onclose = function (event) {
            console.log("❌ WebSocket 연결 종료:", event.code, event.reason);

            if (event.code !== 1000) {
                //scwin.addChatMessage("시스템", "⚠️ 서버와의 연결이 끊어졌습니다. 재연결 시도 중...", false);

                setTimeout(() => {
                    console.log("WebSocket 재연결 시도...");
                    scwin.initializeChatWebSocket();
                }, 5000);
            }
        };

        chatSocket.onerror = function (error) {
            console.error("❌ WebSocket 오류:", error);
            //scwin.addChatMessage("시스템", "❌ 서버 연결 오류 발생", false);
        };

    } catch (error) {
        console.error("❌ WebSocket 초기화 실패:", error);
        //scwin.addChatMessage("시스템", "❌ WebSocket 초기화 실패", false);
    }
};

