// "2025-07-07 06:03:39.0" → "2025년 07월 07일"
scwin.formatDate = function (datetimeStr) {
    const date = new Date(datetimeStr);
    return `${date.getFullYear()}년 ${String(date.getMonth() + 1).padStart(2, "0")}월 ${String(date.getDate()).padStart(2, "0")}일`;
};

// "2025-07-07 06:03:39.0" → "오전 6:03"
scwin.formatTime = function (datetimeStr) {
    const date = new Date(datetimeStr);
    let hour = date.getHours();
    const minute = String(date.getMinutes()).padStart(2, "0");
    const isAM = hour < 12;
    if (hour > 12) hour -= 12;
    if (hour === 0) hour = 12;
    return `${isAM ? '오전' : '오후'} ${hour}:${minute}`;
};


scwin.saveTask = function () {
    //  데이터 보내기
    const formData = new FormData();

    const taskPayload = {
        taskId: scwin.taskInfo.taskId,
        boardId: scwin.taskInfo.boardId,
        projectUserId: scwin.taskInfo.projectUserId,
        projectRepoId: scwin.taskInfo.projectRepoId,
        taskTitle: header_title.getValue(),
        priority: priority_select.getValue(),
        startDate: start_date.getValue(),
        endDate: end_date.getValue(),
        tags: tags_input.getValue(),
        managerVo: manager_input.getValue().split(" ").filter(userId => userId.trim() !== "").map(userId => ({
            managerId: "",
            userId,
            taskId: scwin.taskInfo.taskId
        })),
        content: contents_editor.getHTML()
    };

    formData.append("taskJson", JSON.stringify(taskPayload));

    const allFiles = dls_allFile.getAllJSON();
    const filteredFiles = allFiles.map(file => ({
        fileName: file.fileName,
        filePath: file.filePath,
        fileId: file.fileId,
        taskVersionId: file.taskVersionId
    }));

    formData.append("fileUpload", JSON.stringify(filteredFiles));

    allFiles.forEach((file) => {
        if (file.filePath === undefined || file.filePath === null || file.filePath === "") {
            const blob = scwin.base64ToBlob(file.data, file.type);
            formData.append("files", blob, file.fileName);
        } else {
            const emptyBlob = new Blob([""], { type: file.type || "application/octet-stream" });
            formData.append("files", emptyBlob, file.fileName);
        }
    });

    // 서버로 전송
    $.ajax({
        url: "/InsWebApp/task/update.pwkjson",
        type: "POST",
        data: formData,
        processData: false,
        contentType: false,
        success: async function (res) {
            await $c.win.alert("업무 정보가 저장되었습니다");
        },
        error: async function (err) {
            await $c.win.alert("저장 실패! 다시 시도해주세요");
        }
    });
}

scwin.base64ToBlob = function (base64Data, contentType) {
    const byteString = atob(base64Data.split(',')[1]); // 헤더 제거
    const byteArray = new Uint8Array([...byteString].map(char => char.charCodeAt(0)));
    return new Blob([byteArray], { type: contentType });
}



