scwin.file_remove_onclick = function (e) {
    let chkIdxArr = grd.getCheckedIndex("CHK");
    const size = dls_allFile.getRowCount();

    if (chkIdxArr.length === 0)
        return;

    let checkedItemNums = [];

    for (let i = 0; i < chkIdxArr.length; i++) {
        let rowData = dls_file.getRowJSON(chkIdxArr[i]);
        if (rowData && rowData.num) {
            checkedItemNums.push(rowData.num);
        }
    }

    if (checkedItemNums.length === 0) {
        alert("선택된 항목에서 유효한 고유 식별자(num)를 찾을 수 없습니다.");
        return;
    }

    scwin.removeFileGrid(checkedItemNums, size);

};

scwin.removeFileGrid = function (checkedItemNums, size) {
    let data = dls_allFile.getAllJSON();
    const filteredData = data.filter(row => !checkedItemNums.includes(row.num));
    dls_allFile.setJSON(filteredData);

    const existingList = dls_file.getAllJSON(); // 기존 데이터 추출
    const paramList = [...existingList]; // 기존 데이터 복사
    pageList.setCount(paramList.length === 0 ? 1 : (paramList.length / 5) + 1);

    // ✅ 총 페이지 수 계산
    const totalPages = Math.max(1, Math.ceil(dls_allFile.getRowCount() / 5));
    pageList.setCount(totalPages);

    // ✅ 현재 페이지가 초과됐으면 마지막 페이지로 보정
    if (scwin.filePageIndex > totalPages) {
        scwin.filePageIndex = totalPages;
    } else if (totalPages === 1) {
        scwin.filePageIndex = 1;
    }

    pageList.setSelectedIndex(scwin.filePageIndex);

    // ✅ 페이지에 맞는 데이터 추출
    const startIndex = (scwin.filePageIndex - 1) * 5;
    const endIndex = startIndex + 5;

    const fullList = dls_allFile.getAllJSON();
    const currentPageItems = fullList.slice(startIndex, endIndex);

    // ✅ 화면 표시용 데이터 갱신
    dls_file.setJSON(currentPageItems);

    scwin.removeFileHtml(checkedItemNums, size);
}




scwin.removeFileHtml = function (numList, size) {
    if (!Array.isArray(numList) || numList.length === 0) return;

    let html = contents_editor.getHTML();
    const container = document.createElement("div");
    container.innerHTML = html;

    numList.forEach(num => {
        const target = container.querySelector(`.file-data[data-num="${num}"]`);
        console.log(size - num);

        if (target) {
            const before = target.previousElementSibling;
            const after = target.nextElementSibling;

            if (before && before.tagName === "P" && before.innerHTML.trim() === "<br>") {
                before.remove();
            }
            if (after && after.tagName === "P" && after.innerHTML.trim() === "<br>") {
                after.remove();
            }

            target.remove();
        }
    });

    contents_editor.setHTML(container.innerHTML);
};

scwin.fileInput_change = function (e) {
    const fileInput = $p.$("#fileInput").get(0);
    const files = fileInput.files;
    if (!files || files.length === 0) return;

    const filesArray = Array.from(files);
    let filesReadCount = 0;
    const tempGridList = [];

    for (let i = 0; i < filesArray.length; i++) {
        const file = filesArray[i];
        const reader = new FileReader();

        reader.onload = function (event) {
            const fileDataUrl = event.target.result;

            const param = {
                name: file.name,
                url: fileDataUrl,
                type: file.type,
                num: ++scwin.filePageNum,
                data: fileDataUrl,
                size: file.size
            };

            //1. 에디터에 삽입 (업로드 시에만 실행됨)
            scwin.addFileHtml(param);

            //2. 그리드용 파일 리스트에 넣어두기 (나중에 bulk 추가)
            tempGridList.push(param);
            filesReadCount++;

            //3. 모든 파일 읽은 후 그리드 반영
            if (filesReadCount === filesArray.length) {
                scwin.addFileGrid(tempGridList); // 그리드 추가는 여기서!

                setTimeout(() => {
                    scwin.previousHTML = contents_editor.getHTML(); // 추적
                    console.log(scwin.previousHTML);
                }, 30);
            }
        };

        reader.readAsDataURL(file);


    }
};


//파일 그리드에 파일 추가
scwin.addFileGrid = function (files, num) {
    const dsAll = $p.getComponentById("dls_allFile");
    const allList = dsAll.getAllJSON();
    const newList = [...allList];

    for (let file of files) {
        newList.unshift({
            num: file.num,
            fileName: file.name,
            size: file.size,
            type: file.type,
            data: file.data
        });
    }

    dsAll.setJSON(newList);

    // 페이징 및 화면 갱신
    const totalCount = newList.length;
    const pageSize = 5;
    const pageCount = Math.ceil(totalCount / pageSize);

    const pageList = $p.getComponentById("pageList");
    if (pageList) pageList.setCount(pageCount);

    const dsView = $p.getComponentById("dls_file");
    const currentPage = pageList.getCurrentPage ? pageList.getCurrentPage() : 1;
    const start = (currentPage - 1) * pageSize;
    const end = start + pageSize;
    const viewList = newList.slice(start, end);

    dsView.setJSON(viewList);
};



scwin.addFileHtml = function (file) {
    const html = contents_editor.getHTML();
    const {
        num,
        name,
        size,
        type,
        data,
        url
    } = file;
    let insertHTML = "";

    if (type.startsWith("image/")) {
        // 이미지 직접 삽입
        insertHTML = `<img class="file-data" 
                            data-num="${num}"  
                            data-size="${size}"
                            data = "${data}"
                            data-name = "${name}"
                            data-path = "${url}"  
                            data-type="${type}"
                            src="${url}" 
                            alt="${name}"
                            style="max-width:100%; 
                            margin: 10px 0;" />`;
    } else {
        // 기타 파일은 버튼 또는 다운로드 링크로 처리
        const ext = name.split(".").pop().toLowerCase();

        switch (ext) {
            case "pdf":
                icon = "/InsWebApp/images/fileIcon/pdf.svg";
                break;
            case "hwp":
            case "hwpx":
                icon = "/InsWebApp/images/fileIcon/hwp.svg";
                break;
            case "xls":
            case "xlsx":
            case "csv":
                icon = "/InsWebApp/images/fileIcon/xls.svg";
                break;
            case "doc":
            case "docx":
                icon = "/InsWebApp/images/fileIcon/doc.svg";
                break;
            case "zip":
            case "rar":
            case "7z":
                icon = "/InsWebApp/images/fileIcon/zip.svg";
                break;
            case "txt":
            case "md":
            case "log":
                icon = "/InsWebApp/images/fileIcon/txt.svg";
                break;
            case "html":
            case "htm":
                icon = "/InsWebApp/images/fileIcon/html.svg";
                break;
            case "css":
                icon = "/InsWebApp/images/fileIcon/css.svg";
                break;
            case "js":
                icon = "/InsWebApp/images/fileIcon/js.svg";
                break;
            case "svg":
                icon = "/InsWebApp/images/fileIcon/svg.svg";
                break;
            case "ppt":
            case "pptx":
                icon = "/InsWebApp/images/fileIcon/ppt.svg";
                break;
            case "json":
                icon = "/InsWebApp/images/fileIcon/json.svg";
                break;
            case "yml":
            case "yaml":
                icon = "/InsWebApp/images/fileIcon/yml.svg";
                break;
            case "sql":
                icon = "/InsWebApp/images/fileIcon/sql.svg";
                break;
            case "ttf":
            case "otf":
            case "woff":
            case "woff2":
                icon = "/InsWebApp/images/fileIcon/ttf.svg";
                break;
            default:
                icon = "/InsWebApp/images/fileIcon/etc.svg";
                break;
        }



        insertHTML = `
            <p><br></p>
            <a class="file-data" 
                data-num="${num}"  
                data-size="${size}"
                data = "${data}"
                data-name = "${name}"
                data-path = "${url}"  
                data-type="${type}"
                href="${url}" 
                target="_blank" 
                contenteditable="false"
                style="display: flex; align-items: center; gap: 10px;
                        max-width: 200px; min-width: 100px; padding: 10px;
                        background-color:#fff1d3; border-radius: 6px;
                        border: 1px solid #D9D9D9;
                        box-shadow: 0 2px 6px rgba(0,0,0,0.08);
                        text-decoration: none;">
                <img src="${icon}" alt="${type}" style="width: 50px; height: 50px; border:none; margin:0; padding:0; outline:none;" />
                <span style="font-size: 15px; color: black;">${name}</span>
            </a>
            <p><br></p>
        `;

    }

    contents_editor.setHTML(html + insertHTML);
};

//파일 페이지 번호 클릭
scwin.pageList_onclick = function (index) {
    const dsAll = $p.getComponentById("dls_allFile");
    const dsView = $p.getComponentById("dls_file");

    const allList = dsAll.getAllJSON();
    const pageSize = 5; // 페이지당 보여줄 파일 수
    const start = (index - 1) * pageSize;
    const end = start + pageSize;

    const pageData = allList.slice(start, end);
    dsView.setJSON(pageData);
    scwin.filePageIndex = index;
};

//파일 그리드 셀 클릭
scwin.grd_oncellclick = function (rowIndex, columnIndex, columnId) {
    if (columnId === 'download') {
        let row = dls_file.getRowJSON(rowIndex);
        let targetUrl = row.filePath;
        let fileNanme = row.fileName;
        console.log(row);

        fetch(targetUrl)
            .then(res => res.blob())
            .then(blob => {
                const url = URL.createObjectURL(blob);
                const a = document.createElement("a");
                a.href = url;
                a.download = fileNanme;
                a.click();
                URL.revokeObjectURL(url);
            })
            .catch(err => console.error("❌ 다운로드 실패:", err));

    } else {

    }
};
